      "assessment": {
        "nobel_worthiness": "Horizon-scale black-hole imaging was a remarkable instrumental and observational breakthrough, converting a long-standing possibility into a direct measurement.",
        "attribution": "Falcke, Zensus and Doeleman plausibly represent prediction, very-long-baseline interferometric development and project leadership.",
        "maturity": "The result has been reproduced for multiple targets and strengthened by continuing EHT observations.",
        "uncertainties": [
          "The large collaboration and the division between theoretical prediction, instrumentation and image reconstruction make attribution unusually difficult."
        ]
      }
    },
